import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"历史背景","description":"","frontmatter":{},"headers":[],"relativePath":"中层/历史/index.md","filePath":"中层/历史/index.md","lastUpdated":null}'),l={name:"中层/历史/index.md"};function i(n,a,h,s,d,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="历史背景" tabindex="-1">历史背景 <a class="header-anchor" href="#历史背景" aria-label="Permalink to &quot;历史背景&quot;">​</a></h1><blockquote><p>本页收录的是<strong>历史的真相版本</strong>（中层历史）。表层流传的历史记载见<a href="./../../表层/历史/" class="layer-link" data-layer="表层">表层历史</a>——真相与记载的差异，正是本层的价值所在。</p></blockquote><p>历史背景文档涵盖神造物世界观中从远古到当代的完整时间线。主线历史按时间顺序分为前传、间章与正传（福瑞时代）三段：前传是人类超算纪元的背景与剧情，间章是前传与正传之间的过渡，正传是福瑞时代的中层编年史。另有《火种故事》作为黑暗时代的故事化补全。</p><h2 id="概念诠释" tabindex="-1">概念诠释 <a class="header-anchor" href="#概念诠释" aria-label="Permalink to &quot;概念诠释&quot;">​</a></h2><p>主线历史部分涵盖神造物世界观的核心历史脉络，按时间顺序分为前传、间章与正传（福瑞时代）三段：前传是人类超算纪元的背景与剧情，间章是前传与正传之间的过渡，正传是福瑞时代的中层编年史。</p><h2 id="主要内容" tabindex="-1">主要内容 <a class="header-anchor" href="#主要内容" aria-label="Permalink to &quot;主要内容&quot;">​</a></h2><h3 id="_1-正传历史" tabindex="-1">1. 正传历史 <a class="header-anchor" href="#_1-正传历史" aria-label="Permalink to &quot;1. 正传历史&quot;">​</a></h3><p>福瑞时代的中层编年史：从共同体建立到当前鹿熊冷战时代的真实脉络，与表层历史三篇（共同体时期/黑暗时代/当前时代）一一对照。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./正传历史">正传历史</a></p></blockquote><h3 id="_2-火种故事" tabindex="-1">2. 火种故事 <a class="header-anchor" href="#_2-火种故事" aria-label="Permalink to &quot;2. 火种故事&quot;">​</a></h3><p>《神造物·火种》故事概要：黑暗时代早期，普通生灵点燃第一簇反抗火种的故事。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./火种故事">火种故事</a></p></blockquote><h3 id="_3-间章历史" tabindex="-1">3. 间章历史 <a class="header-anchor" href="#_3-间章历史" aria-label="Permalink to &quot;3. 间章历史&quot;">​</a></h3><p>前传与正传之间的过渡时期历史，包含神机登神、布局新世界的关键过程。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./间章历史">间章历史</a></p></blockquote><h3 id="_4-前传历史" tabindex="-1">4. 前传历史 <a class="header-anchor" href="#_4-前传历史" aria-label="Permalink to &quot;4. 前传历史&quot;">​</a></h3><p>前传完整剧情线（林月视角）与前传关键机制。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./前传历史">前传历史</a></p></blockquote><h3 id="_5-前传超算纪元" tabindex="-1">5. 前传超算纪元 <a class="header-anchor" href="#_5-前传超算纪元" aria-label="Permalink to &quot;5. 前传超算纪元&quot;">​</a></h3><p>前传背景与&quot;人物/技术志&quot;：人类超算时代的核心背景、技术路线与核心超算角色档案。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./前传超算纪元">前传超算纪元</a></p></blockquote><h2 id="阅读建议" tabindex="-1">阅读建议 <a class="header-anchor" href="#阅读建议" aria-label="Permalink to &quot;阅读建议&quot;">​</a></h2><ol><li><strong>以史为纲</strong>：建议先读<a href="./正传历史">正传历史</a>，与已读的表层历史逐段对照，再依次读火种故事 → 间章历史 → 前传历史 → 前传超算纪元</li><li><strong>随时跳出</strong>：遇到提及的世界真相（神机谋划、地脉与魔法、太空巨构等）可跳至<a href="./../">中层世界真相</a>相关条目，读完再回来</li><li><strong>注意层级</strong>：越往前追溯越接近底层元规则，跨层链接均带徽标</li></ol><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../../表层/历史/" class="layer-link" data-layer="表层">表层历史</a></li><li><a href="./正传历史">正传历史</a></li><li><a href="./火种故事">火种故事</a></li><li><a href="./间章历史">间章历史</a></li><li><a href="./前传历史">前传历史</a></li><li><a href="./前传超算纪元">前传超算纪元</a></li><li><a href="./../">中层世界真相</a></li><li><a href="./../../表层/" class="layer-link" data-layer="表层">世界设定</a></li></ul><hr>',27)])])}const f=e(l,[["render",i]]);export{p as __pageData,f as default};
